/**
@typedef {{
  unit?: ("inch" | "pica" | "point" | "em" | "pixel"),
  value?: number,
  px: number
}} Unit

*/
class ScaleEngine{
  constructor(scale = 1){
    this.scale = scale
    this._dpi = window.devicePixelRatio
    this.dpi = this._dpi * 96
  }

  /**
  @param {number} value 
  @returns {Unit} 
  */
  em(value){
    return {
      unit:"em",
      value,
      px: this.inch(value/6).px
    }
  }

  ems(value) {return this.em(value)}

  /**
  @param {number} value 
  @returns {Unit} 
  */
  px(value){
    return {
      unit: "pixel",
      value,
      px: value*this.scale
    }
  }
  pixel(value){return this.px(value)}

  /**
  @param {number} value 
  @returns {Unit} 
  */
  inch(value){
    return { 
      unit: "inch",
      value,
      px: value * this.dpi * this.scale
    }
  }

  inches(value){return this.inch(value) }

  /**
  @param {number} value 
  @returns {Unit} 
  */
  pica(value){ return this.em(value) }
  picas(value){return this.pica(value)}


  point(value){
    return {
      unit: "point",
      value,
      px: this.pica(value).px / 12
    }
  }

}

